import { describe, expect, it } from "vitest"
import { quoteCsvCell } from "../src/Csv.js"

describe("quoteCsvCell", () => {
  const cases = [
    ["", ""],
    ["invoice-42", "invoice-42"],
    ["café", "café"],
    ["Smith, Jane", '"Smith, Jane"'],
    ['a"b', '"a""b"'],
    ["first\nsecond", '"first\nsecond"'],
    ["first\rsecond", '"first\rsecond"'],
    ["first\r\nsecond", '"first\r\nsecond"'],
    ['a,"b"', '"a,""b"""']
  ] as const

  it.each(cases)("encodes %j as %j", (input, expected) => {
    expect(quoteCsvCell(input)).toBe(expected)
  })

  describe("comma handling", () => {
    it("wraps a cell containing a comma", () => {
      expect(quoteCsvCell("Smith, Jane")).toBe('"Smith, Jane"')
    })

    it("preserves the comma inside the quoted cell", () => {
      expect(quoteCsvCell("Smith, Jane")).toBe('"Smith, Jane"')
    })

    it("includes both names in the result", () => {
      const result = quoteCsvCell("Smith, Jane")
      expect(result).toContain("Smith")
      expect(result).toContain("Jane")
      expect(result).toContain(",")
    })
  })
})
